    | 'ALREADY_DEPARTED'
    /** Refundable, less whatever the cabin's fee comes to. */
    | 'REFUNDABLE'
    /** Cancellable, but too close to departure to be worth anything back. */
    | 'INSIDE_CUTOFF'
    /** The airline caused this, so the fare rules do not apply. */
    | 'DISRUPTED';

