                                                <dt>Departs</dt>
                                                <dd>{leg.departureReadable}</dd>
                                            </div>
                                            <div>
                                                <dt>Confirmation</dt>
                                                <dd>{leg.reference}</dd>
                                            </div>
                                            <div>
                                                <dt>Check-in opens</dt>
                                                <dd>{leg.opensAtReadable}</dd>
                                            </div>
                                            <div>
                                                <dt>Check-in closes</dt>
                                                <dd>{leg.closesAtReadable}</dd>
                                            </div>
