    passengerId: overrides.passengerId ?? 'p1',
    seatNumber: overrides.seatNumber ?? '11A',
    cabinClass: 'ECONOMY' as const,
    releasedAt: overrides.releasedAt ?? null,
    checkedInAt: overrides.checkedInAt ?? null,
});

