    await book([outbound.id, inbound.id], [['1A', '1A'], ['1B', '1B']]);
    await book([cancelled.id], [['2A']]);
    await prisma.flight.update({ where: { id: cancelled.id }, data: { status: 'CANCELLED' } });

    console.log(`fixture ready: ${email} / Password123!`);
}

main().finally(() => prisma.$disconnect());
