 * defects this layout could reproduce are both horizontal overflow at phone
 * width -- checkout (#193) and the seat map (#256). Nothing here is given a
 * fixed width, and the facts list collapses to one column rather than
 * scrolling.
 *
 * Every colour below is checked against the panel it sits on rather than
 * against pure black: the caption greys that failed AA did so because they were
 * chosen against the darker page (#199, #250, #290).
 */
.checkin-shell {
  width: min(100%, 60rem);
  min-width: 0;
}

.checkin-shell h1 {
  margin: 0 0 0.5rem;
  font-size: clamp(1.75rem, 5vw, 2.4rem);
  color: #fff;
}

.checkin-intro {
  margin: 0 0 2rem;
  /* 8.6:1 on the page background. */
  color: #d4d4d8;
  max-width: 44rem;
}

.checkin-empty {
  padding: 1.5rem;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 1rem;
  background: rgba(255, 255, 255, 0.04);
  color: #e5e7eb;
}

.checkin-empty a,
.checkin-link {
  color: #d8b4fe;
  font-weight: 700;
}

.checkin-leg-list {
  display: grid;
  gap: 1.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.checkin-card {
  min-width: 0;
  padding: clamp(1rem, 3vw, 1.75rem);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 1rem;
  background: rgba(255, 255, 255, 0.04);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
}

.checkin-card-head {
  display: flex;

